from layout import *
def simulator():
    s=J('retention/results/summary.json')
    def stat(contract,rho,pol,metric,delta=False):
        key='contrasts_positive_favor_joint' if delta else 'estimates'
        return next(v for v in s[key] if (v['tool'],v['rho'],v['policy'],v['metric'])==(contract,rho,pol,metric))
    page('Опыт 3   /   стоимость хранения','Какие факты сохранять вместе','Если один вызов инструмента возвращает сразу четыре поля, сохранение одного из них может ничего не сэкономить. Другие поля всё равно заставят агента прочитать тот же источник.')
    p('В каждом из 64 миров имеется 8 источников по 4 значения. Кэш вмещает 8 полей. Нужны от двух до четырёх значений, доступно два чтения. В первом режиме за чтение возвращаются четыре поля источника, во втором — только указанное поле. Внутри мира меняется вероятность ρ совместного выбора скрытого ранга нужных полей. Физические источники после перестановки могут различаться даже при ρ = 1.')
    p('96 прошлых запросов доступны для настройки, 48 для выбора базового метода. Затем все политики построены на одинаковых 144 запросах. Следующие 128 используются только для проверки. Восемь записей в кэше занимают 40 байт в компактном представлении «ключ и значение». Состояние обучения и история запросов учитываются отдельно. На тестовой части кэш фиксирован. При каждом запросе симулятор действительно читает доступные значения и сверяет собранный ответ с исходными данными.')
    rows=[]
    names={'joint':'Совместный выбор','marginal':'Частота полей','whole_block':'Целые блоки','recent':'Последние поля','validation_choice':'Выбор на валидации'}
    for mode,label in [('block','Блок'),('field','Поле')]:
        for pol,descr in names.items():
            row=[stat(mode,'all',pol,m)['mean'] for m in ['required_reads','actual_reads','returned_values','correct']]
            rows.append([label,descr]+[dec(v,3) for v in row[:3]]+[perc(row[3])])
    tbl(['Чтение','Политика записи','Нужно чтений','Сделано чтений','Получено полей','Всё верно'],rows,[2.05,4.05,2.8,2.85,2.75,2.6],True)
    p('Среднее по запросам, затем по трём режимам ρ и 64 мирам. «Нужно» — сколько обращений потребовалось бы для полного ответа без ограничения. «Сделано» — фактическое число, максимум два. «Получено полей» учитывает всё возвращённое инструментом, включая незапрошенные значения. Поля из кэша учитываются отдельно. Совместный выбор минимизирует ожидаемое число необходимых чтений на доступной истории, распределяя слоты динамическим программированием.','Caption')
    page('Опыт 3   /   размер эффекта','Когда совместный выбор окупается','Относительно восьми самых частых полей совместный выбор в среднем экономит 0,0188 необходимого блочного чтения на запрос. Преимущество заметнее, когда связанные сведения часто запрашивают вместе.')
    first=stat('block','all','validation_choice','required_reads',True)
    p(f"Основной заранее заданный соперник — выбор между тремя простыми политиками по валидационной выборке. Экономия составляет {dec(first['mean'],4)} чтения на запрос. Для этой разности 95%-й парный t-интервал по 64 мирам {ci(first)}. Перевыборка 10 000 раз целых миров даёт [{dec(s['primary_bootstrap95'][0],4)}; {dec(s['primary_bootstrap95'][1],4)}]. Сильнейшая фиксированная база по среднему тестовому результату — частота полей. Её выбор как самого сильного соперника ретроспективен.")
    rows=[]
    for rho in [0,50,100,'all']:
        d=stat('block',rho,'marginal','required_reads',True);f=stat('block',rho,'marginal','correct',True)
        rows.append([('Среднее' if rho=='all' else dec(rho/100,1)),dec(d['mean'],4),ci(d),f"[{dec(d['family_lower95'],4)}; {dec(d['family_upper95'],4)}]",pp(f['mean'],2)])
    tbl(['Зависимость ρ','Чтений сэкономлено','95% ДИ','ДИ с поправкой¹','Точность, п.п.'],rows,[2.5,3.1,4.05,4.25,3.2],True)
    doc.add_picture(str(HERE/'retention-plot.png'),width=Cm(15.7));doc.paragraphs[-1].alignment=WD_ALIGN_PARAGRAPH.CENTER
    p('Точки и отрезки показывают экономию относительно частотной политики и её обычный 95%-й ДИ. Справа от нуля требуется меньше чтений. ¹ Одновременные интервалы Бонферрони покрывают 16 запланированных блочных сравнений.','Caption')
    h('Где меняется вывод')
    p('При поштучном чтении совместный и частотный выбор дали одни и те же результаты на всех 24 576 тестовых запросах. При ρ = 1 целые блоки дали больше полностью правильных ответов в бюджете двух вызовов, чем совместный выбор (94,73% против 93,12%), хотя потребовали в среднем на 0,2806 больше чтения для полного ответа. Оптимизация среднего расхода и соблюдение жёсткого бюджета — разные цели.')
    p('Это результат механизма на неизменных значениях с известной схемой. Дополнительные расходы на компиляцию кэша, устаревание полей, ошибки LLM при извлечении значения из ответа и цена реального API определят практическую окупаемость.')

def appendix():
    x=C('search/observations.csv');y=C('search_replication/observations.csv')
    page('Приложение   /   первичные исходы','Поиск по каждому символу','В каждой ячейке три результата в порядке «пересказ / сырой журнал / карточка». 1 означает, что выполненная команда вернула точную строку определения, 0 — что строка осталась ненайденной.')
    cl={'output_clipping':'Лимит строк','file_glob':'Маска файлов','working_directory':'Каталог','hidden_directory':'Скрытые файлы'}
    def get(rows,k):return '/'.join(str(next(r['pass'] for r in rows if r['case']==k and r['arm']==arm)) for arm in ('summary','raw','structured'))
    rows=[]
    for k in sorted(set(r['case'] for r in x)):
        r=next(r for r in x if r['case']==k)
        rows.append([k,r['symbol'],cl.get(r['mechanism'],r['mechanism']),r['target_line'],'2' if r['ambiguous']=='True' else '1',get(x,k),get(y,k)])
    tbl(['ID','Символ','Механизм','Строка','Вариантов','Sol','Luna'],rows,[1.05,4.6,3.45,1.55,2.55,1.95,1.95],True)
    h('Допустимые и правильные действия')
    p('«Вариантов» — число каталогов, в которых прошлый поиск ещё допускал определение. Для каждого запуска сохранены предложенные команды, выбранная буква, фактическая команда, stdout, код завершения и точный ожидаемый путь. Одинаковая задача под разными представлениями давалась разным сессиям. Различия между моделями рассчитаны на тех же заданиях.')
    page('Приложение   /   полный набор исходов','Перенос пробы по каждому случаю','Показано количество верных предсказаний из четырёх. Основной показатель «задача решена» требует 4/4. В архиве записаны также каждое входное значение, его фактический результат и ответ агента.')
    ss=J('probe/scores.json');rows=[]
    for k in sorted(set(v['case'] for v in ss)):
        vals={a['arm']:a for a in ss if a['case']==k};v=next(iter(vals.values()))
        rows.append([k,v['family'],'Стабильная' if v['stable'] else 'Возврат',*[vals[a]['n_correct'] for a in ('discriminating','ordinary','fresh')]])
    tbl(['ID','Семейство','Режим','Различающий','Обычный','С нуля'],rows,[2,3.0,3.7,3.0,2.7,2.7],True)
    h('Реальные пакеты')
    sb=J('probe_real/scores.json');rlist=[]
    for name in sorted({(v['project'],v['version']) for v in sb}):
        a={v['arm']:v for v in sb if (v['project'],v['version'])==name}
        rlist.append([name[0],name[1],str(sum(a['archive']['correct_bits']))+'/4',str(sum(a['fresh']['correct_bits']))+'/4'])
    tbl(['Пакет','Целевой релиз','Исторический пример','Свежая проба'],rlist,[4.3,3.8,4.8,4.2],True)
    page('Приложение   /   внешние истории','Частота ограничений по проектам')
    field=J('field/summary.json')
    rows=[[k.replace('__','/'),v['n'],v['with_search'],v['with_limit'],v['search_commands'],v['limited_commands']] for k,v in field['repos'].items()]
    tbl(['Проект','Историй','С поиском','С лимитом','Команд поиска','Из них с лимитом'],rows,[5.35,2.0,2.05,2.1,2.7,2.9],True)
    h('Что доступно для независимой проверки')
    p('В field/sample.json перечислены все 48 исходных путей, в traces.jsonl — SHA-256 каждого исходного файла и все распознанные команды со ссылкой на сообщение и ответ. verification_examples.json хранит вручную проверенные примеры. Внешний аудит повторно скачал исходники и воспроизвёл случай фактического обрезания у eodag.')
    h('Все симуляционные результаты')
    p('retention/results/worlds.csv содержит каждое сочетание мира, зависимости, контракта и политики (1 920 строк). jobs.csv.gz описывает входы, steps.csv.gz содержит все 245 760 исполнений, полученные значения закодированы через идентификаторы и битовые маски относительно снимка в builds.json. Расшифровка и проверка даны в README и verify.py. Все эти файлы вложены в этот Word-документ вместе с программами и предоставлены также отдельным ZIP.')

